pub fn all() -> Vec<&'static str> {
    let mut v = vec![LEDE, HINT];
    for group in [&QUESTION[..], &BACKGROUND[..], &RATIONALE[..], &PURPOSE[..], &INTUITION[..], &MATHEMATICS[..], &EXPERIMENT[..], &RUN[..], &ANALYSIS[..], &EXTENSION[..], &SUMMARY[..], &NEXT[..], &CODE[..]] {
        v.extend_from_slice(group);
    }
    v
}
